/**
 * The ways in: a compact card for an account whose notebooks are still small
 * (owner, 2026-10-17; reworked for the first visit to Today, uiux
 * 2026-10-22-today-first-visit M3, owner-approved 22 Oct 2026).
 *
 * With words it is "Save words where you meet them": the routes for the
 * places the learner said they meet words in onboarding (`waysFor`), each with
 * the product's own mark. With an empty notebook it is "Or bring in words you
 * already have", the deck import first. It replaced both "More ways to bring
 * in words" and the getting-started chip in Today's corner, which said the
 * same thing twice. It sits below the day's plan, never above it, until the
 * notebook has grown or the learner puts it away.
 */
import { Link } from 'react-router-dom';
import { Icon } from '@/components/ui/Icon.js';
import { getMeta, setMeta, type MetaShape } from '@/db/schema.js';
import { settingsPath } from '@/features/settings/paths.js';
import { t, type MessageKey } from '@/i18n/index.js';
import { DEFAULT_ACCELERATOR, prettyShortcut } from '@/lib/desktopShortcut.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { offersWaysIn } from './offer.js';
import { WayMark } from './WayMark.js';
import { waysFor, type WayId } from './ways.js';
import styles from './WaysIn.module.css';

/** Each way, to the screen that already does it. */
const WAYS: Readonly<Record<WayId, { to: string; title: MessageKey; line: MessageKey }>> = {
  import: { to: settingsPath('data'), title: 'waysIn.importTitle', line: 'waysIn.importLine' },
  kindle: { to: settingsPath('data'), title: 'waysIn.kindleTitle', line: 'waysIn.kindleLine' },
  web: { to: settingsPath('everywhere'), title: 'waysIn.webTitle', line: 'waysIn.webLine' },
  watch: { to: settingsPath('everywhere'), title: 'waysIn.watchTitle', line: 'waysIn.watchLine' },
  list: { to: '/ai', title: 'waysIn.listTitle', line: 'waysIn.listLine' },
  assistants: {
    to: settingsPath('connected-apps'),
    title: 'waysIn.assistantsTitle',
    line: 'waysIn.assistantsLine',
  },
};

/** The card, or nothing once the notebook has grown or it was put away. */
export function WaysIn({ words }: { words: number }): React.JSX.Element | null {
  // Undefined until read, so a learner who put it away never sees it flash.
  const dismissed = useLiveQuery<boolean | undefined>(() => getMeta('waysInDismissed'), undefined, []);
  // Undefined until read too: drawn with the default routes first, the card
  // reordered itself under the reader a frame later.
  const sources = useLiveQuery<MetaShape['wordSources'] | undefined>(
    () => getMeta('wordSources'),
    undefined,
    [],
  );
  if (dismissed === undefined || sources === undefined || !offersWaysIn(words, dismissed)) return null;
  return (
    <section className={styles.card} aria-labelledby="ways-in-title">
      <div className={styles.head}>
        <h2 id="ways-in-title" className={styles.title}>
          {t(words === 0 ? 'waysIn.titleEmpty' : 'waysIn.title')}
        </h2>
        <button
          type="button"
          className={styles.close}
          aria-label={t('waysIn.hide')}
          onClick={() => {
            void setMeta('waysInDismissed', true);
          }}
        >
          <Icon name="close" size={16} weight={2} />
        </button>
      </div>
      <ul className={styles.list}>
        {waysFor(words, sources).map((id) => (
          <li key={id}>
            <Link to={WAYS[id].to} className={styles.row}>
              <WayMark way={id} />
              <span className={styles.text}>
                <span className={styles.rowTitle}>{t(WAYS[id].title)}</span>
                <span className={styles.line}>{lineOf(id)}</span>
              </span>
              <Icon name="chevronRight" size={16} weight={2} className={styles.chevron} />
            </Link>
          </li>
        ))}
      </ul>
    </section>
  );
}

/** A way's line; the desktop shortcut is said as the keys this device's app uses. */
function lineOf(id: WayId): React.ReactNode {
  if (id !== 'watch') return t(WAYS[id].line);
  const [before = '', middle = '', after = ''] = t('waysIn.watchLine', { mac: '\u0000', pc: '\u0000' }).split(
    '\u0000',
  );
  return (
    <>
      {before}
      <kbd className={styles.kbd}>{prettyShortcut(DEFAULT_ACCELERATOR, true)}</kbd>
      {middle}
      <kbd className={styles.kbd}>{prettyShortcut(DEFAULT_ACCELERATOR, false)}</kbd>
      {after}
    </>
  );
}
